package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;
import com.ruoyi.medical.contracts.*;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;

/** Original AT10 facts, not an active tool token or a new waiting decision. */
public final class TaskPlanDraftSavedToolReceipt {
    private final JdbcTemplate db;private final TaskPlanDraftSchema schema;
    public TaskPlanDraftSavedToolReceipt(DataSource data,TaskPlanDraftSchema schema){db=new JdbcTemplate(data);db.setQueryTimeout(5);this.schema=schema;}
    Verified require(TaskPlanDraftSavedCandidate.Verified candidate)throws Exception {
        candidate.requireUnchanged();var j=candidate.job();var rows=db.queryForList("SELECT * FROM task_plan_draft_tool_receipt WHERE tenant_id=? AND project_id=? AND task_id=? AND run_id=? AND candidate_receipt_sha256=? LIMIT 2",j.tenant(),j.project(),j.task(),j.run(),candidate.receiptSha256());var row=one(rows);
        var receipt=schema.validate("ToolReceipt",schema.read(str(row,"receipt_json")));if(!schema.hash(receipt).equals(row.get("receipt_sha256"))||!schema.canonical(receipt).equals(row.get("receipt_json")))bad();
        for(var e:Map.of("tenant_id",j.tenant(),"project_id",j.project(),"task_id",j.task(),"task_revision",j.taskRevision(),"run_id",j.run(),"actor_id",j.actor(),"artifact_id",candidate.artifactId(),"input_sha256",j.inputHash(),"candidate_receipt_sha256",candidate.receiptSha256()).entrySet())if(!e.getValue().equals(receipt.required(e.getKey()).asText()))bad();
        for(String field:List.of("session_id","call_id","request_sha256","candidate_receipt_sha256","check_receipt_sha256"))if(!receipt.required(field).asText().equals(row.get(field)))bad();
        if(!j.actor().equals(row.get("created_by"))||!"1.0.0".equals(row.get("schema_version"))||!schema.manifest().equals(row.get("schema_manifest_sha256"))||!j.classification().equals(row.get("classification")))bad();
        var action=one(db.queryForList("SELECT * FROM step_action_binding WHERE tenant_id=? AND run_id=? AND step_id=? AND action_id=? LIMIT 2",j.tenant(),j.run(),receipt.required("step_id").asText(),receipt.required("action_id").asText()));
        var args=schema.tree(Map.of("plan_artifact_id",candidate.artifactId()));if(!"TOOL_CALL".equals(action.get("kind"))||!schema.hash(args).equals(action.get("arguments_sha256"))||!j.actor().equals(action.get("created_by"))||!j.inputHash().equals(action.get("input_sha256"))||!receipt.required("lease_generation").asText().equals(action.get("lease_generation").toString()))bad();
        var dispatched=one(db.queryForList("SELECT resource_ref,subject_id,result FROM audit_event WHERE tenant_id=? AND audit_id=? AND action='task.plan_draft.save.dispatched' LIMIT 2",j.tenant(),receipt.required("action_id").asText()));var request=schema.read(str(dispatched,"resource_ref"));
        if(!j.actor().equals(dispatched.get("subject_id"))||!"SUCCESS".equals(dispatched.get("result"))||!receipt.required("request_sha256").asText().equals(schema.hash(request))||!args.equals(request.required("arguments"))||!receipt.required("session_id").asText().equals(request.required("session_id").asText())||!receipt.required("call_id").asText().equals(request.required("call_id").asText())||!"AT-10".equals(request.required("tool_id").asText())||!action.get("tool_version").equals(request.required("tool_version").asText()))bad();
        var originalCheck=one(db.queryForList("SELECT receipt_json FROM task_plan_draft_check WHERE tenant_id=? AND run_id=? AND receipt_sha256=? AND candidate_receipt_sha256=? LIMIT 2",j.tenant(),j.run(),receipt.required("check_receipt_sha256").asText(),candidate.receiptSha256()));var check=schema.validate("CheckReceipt",schema.read(str(originalCheck,"receipt_json")));if(!schema.hash(check).equals(receipt.required("check_receipt_sha256").asText())||!candidate.artifactId().equals(check.required("target_revision").asText())||!schema.hash(candidate.candidate()).equals(check.required("target_sha256").asText()))bad();
        var waiting=one(db.queryForList("SELECT * FROM waiting_item WHERE tenant_id=? AND waiting_item_id=? LIMIT 2",j.tenant(),receipt.required("waiting_item_id").asText()));if(!j.run().equals(waiting.get("run_id"))||!candidate.artifactId().equals(waiting.get("target_revision"))||!receipt.required("action_id").asText().equals(waiting.get("action_id"))||!"CONFIRM_PLAN".equals(waiting.get("reason_code"))||!Set.of("WAITING_INPUT","RESOLVED","CANCELLED").contains(waiting.get("status")))bad();
        var audit=one(db.queryForList("SELECT * FROM audit_event WHERE tenant_id=? AND audit_id=? LIMIT 2",j.tenant(),row.get("audit_id")));var event=one(db.queryForList("SELECT * FROM outbox_event WHERE tenant_id=? AND event_id=? LIMIT 2",j.tenant(),row.get("event_id")));if(!j.actor().equals(audit.get("subject_id"))||!"SUCCESS".equals(audit.get("result"))||!"task.plan_draft.save.completed".equals(audit.get("action"))||!receipt.equals(schema.read(str(audit,"resource_ref")))||!j.run().equals(event.get("aggregate_id"))||!"task.plan_draft.save.completed".equals(event.get("event_type"))||!receipt.equals(schema.read(str(event,"payload"))))bad();
        candidate.requireUnchanged();return new Verified(candidate,receipt);
    }
    public final class Verified {private final TaskPlanDraftSavedCandidate.Verified candidate;private final JsonNode receipt;private Verified(TaskPlanDraftSavedCandidate.Verified candidate,JsonNode receipt){this.candidate=candidate;this.receipt=receipt.deepCopy();}void requireUnchanged()throws Exception{if(!receipt.equals(require(candidate).receipt))bad();}JsonNode receipt(){return receipt.deepCopy();}}
    private static String str(Map<String,Object> r,String k){if(!(r.get(k) instanceof String))bad();return (String)r.get(k);}private static <T>T one(List<T> r){if(r.size()!=1||r.get(0)==null)bad();return r.get(0);}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
}
